#!/usr/bin/env python3
"""Checker for documentation generated by documake.

Usage: check_docs.py <repo-root> [--docs docs] [--lang es|en|<code>] [--mermaid] [--json]
       check_docs.py <repo-root> --audit README.md CLAUDE.md ...   (drift in pre-existing docs)

Checks that what is written is true (paths and symbols exist) and that it
follows the constitution (no line numbers, complete module cards, no builder
perspective). Language defaults to _meta/documake.json "language", else "es".
Exits 1 on errors.
"""
import argparse
import json
import os
import re
import shutil
import subprocess
import sys
import tempfile
import unicodedata

